data.stateMemoryCode:
{
  "user_requirement": {
    "value": (x, y) => y ?? x,
    "default": () => ""
  },
  "requirement_analysis": {
    "value": (x, y) => y ?? x,
    "default": () => ""
  },
  "tech_research": {
    "value": (x, y) => y ?? x,
    "default": () => ""
  },
  "implementation_plan": {
    "value": (x, y) => y ?? x,
    "default": () => ""
  },
  "review_feedback": {
    "value": (x, y) => (Array.isArray(y) ? x.concat(y) : x.concat([y])),
    "default": () => []
  },
  "review_passed": {
    "value": (x, y) => y ?? x,
    "default": () => false
  },
  "iteration_count": {
    "value": (x, y) => y ?? x,
    "default": () => 0
  }
}

data.updateStateMemoryCode:
const output = $flow.output.content;
const reviewPassed = output.includes('REVIEW_RESULT: PASS');
return {
  "review_feedback": $flow.state.review_feedback.concat([output]),
  "review_passed": reviewPassed
};

data.conditionFunction:
const state = $flow.state;
const messages = state.messages;
const lastMessage = messages[messages.length - 1];
const iterationCount = parseInt(state.iteration_count) || 0;

// 超过3次迭代强制通过
if (iterationCount >= 3) {
    return "final_adjustor";
}

// 评审通过
if (lastMessage.content.includes("REVIEW_RESULT: PASS")) {
    return "final_adjustor";
}

// 需要修改
return "solution_architect";
